    if apply_instance_condition {
        let inst = get_inst_value(&ctxt);
        if is_output {
            let lhs = Expr::Verbatim(quote! { #param_name.instance_id() });
            inst_eq_enss.push(Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::equal(#lhs, #inst)
